): IEcommerceMallSellerApproval.ICreate {
  const status =
    input?.status ?? RandomGenerator.pick(["approved", "rejected"] as const);
  return {
    sellerId: input?.sellerId ?? typia.random<string & tags.Format<"uuid">>(),
