    requestDetails.reviewed_reason,
    null,
  );
  TestValidator.equals(
    "request id preserved",
    requestDetails.id,
    adminRequest.id,
  );
  TestValidator.equals(
    "actor_type is seller",
    requestDetails.actor_type,
    "seller",
  );
  TestValidator.equals(
    "requested_grade preserved",
    requestDetails.requested_grade,
    adminRequest.requested_grade,
  );
}

