/**
 * Test retrieving a refund request snapshot with a non-existent UUID.
 *
 * Prerequisites Setup:
 * 1. Authenticate as an administrator using POST /ecommerceMall/auth/admin/join
 *
 * Test Steps:
 * 1. Generate a UUID that does not exist in the system
 * 2. Call GET /ecommerceMall/customer/refund-request-snapshots/{snapshotId} with the non-existent UUID
 * 3. Use valid admin authentication token
 * 4. Verify proper 404 error response
 *
 * Expected Result:
 * - HTTP 404 Not Found returned
 * - Error message indicates the snapshot was not found
 */
export async function test_api_refund_request_snapshot_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as administrator
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16) as string &
        tags.Format<"password">,
      name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // 2. Generate a non-existent UUID
  const nonExistentSnapshotId = typia.random<string & tags.Format<"uuid">>();
  // 3. Attempt to retrieve non-existent snapshot and expect 404 error
  await TestValidator.httpError(
    "refund request snapshot not found",
    404,
    async () =>
      api.functional.ecommerceMall.customer.refund_request_snapshots.at(
        adminConnection,
        {
          snapshotId: nonExistentSnapshotId,
        },
      ),
  );
}

