/**
 * Test retrieving a shipping address that has been soft-deleted.
 *
 * This test validates that soft-deleted addresses are not accessible through
 * the retrieve endpoint. The scenario:
 * 1. Register a new customer account
 * 2. Create a shipping address for the customer
 * 3. Delete the shipping address using the delete endpoint
 * 4. Attempt to retrieve the deleted address by its ID
 * 5. Verify the API returns a 404 error indicating the address was not found
 *
 * This confirms that soft-deleted addresses are properly excluded from
 * retrieval queries.
 */
export async function test_api_customer_address_retrieval_deleted(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a new customer
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // 2. Create a shipping address
  const address =
    await generate_random_ecommerce_mall_customer_customers_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // 3. Delete the shipping address
  await api.functional.ecommerceMall.customer.addresses.erase(
    customerConnection,
    {
      addressId: address.id,
    },
  );
  // 4. Attempt to retrieve the deleted address
  // 5. Verify the API returns a 404 error
  await TestValidator.httpError(
    "deleted address should return 404",
    404,
    async () => {
      await api.functional.ecommerceMall.customer.addresses.at(
        customerConnection,
        {
          addressId: address.id,
        },
      );
    },
  );
}

