export async function test_api_seller_profile_snapshot_retrieval_by_owner(
  connection: api.IConnection,
): Promise<void> {
  // Setup: Create admin account for seller approval
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16) as string &
        tags.Format<"password">,
      name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // Create seller account with pending approval status
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerJoinResult = await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword as string & tags.Format<"password">,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // Admin approves the seller registration
  await generate_random_ecommerce_mall_admin_seller_approvals_create(
    adminConnection,
    {
      body: {
        sellerId: sellerJoinResult.id,
        status: "approved",
      },
    },
  );
  // Seller logs in with approved status to get JWT tokens
  const sellerLoginResult = await authorize_seller_login(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // First profile update - creates initial snapshot
  const initialShopName = RandomGenerator.name();
  const initialDescription = RandomGenerator.paragraph({ sentences: 2 });
  const initialUpdate =
    await api.functional.ecommerceMall.seller.seller.profile.update(
      sellerConnection,
      {
        body: {
          name: initialShopName,
          description: initialDescription,
        },
      },
    );
  typia.assert(initialUpdate);
  // Extract snapshot ID from the first update response
  // The API returns snapshot metadata that we can use to retrieve the snapshot
  const firstSnapshotId =
    (initialUpdate as any).snapshot_id ?? (initialUpdate as any).snapshotId;
  // Second profile update - creates another snapshot (capturing state from first update)
  const updatedShopName = RandomGenerator.name();
  const updatedDescription = RandomGenerator.paragraph({ sentences: 3 });
  const updatedLogoUri = `https://example.com/logos/${RandomGenerator.alphaNumeric(10)}.png`;
  const finalUpdate =
    await api.functional.ecommerceMall.seller.seller.profile.update(
      sellerConnection,
      {
        body: {
          name: updatedShopName,
          description: updatedDescription,
          logoUri: updatedLogoUri,
        },
      },
    );
  typia.assert(finalUpdate);
  // The second update's snapshot captures the state from the first update
  const snapshotId =
    firstSnapshotId ??
    (finalUpdate as any).snapshot_id ??
    (finalUpdate as any).snapshotId;
  // Retrieve the snapshot created by the second profile update
  const snapshot =
    await api.functional.ecommerceMall.seller.profile.snapshots.at(
      sellerConnection,
      {
        snapshotId: snapshotId!,
      },
    );
  typia.assert(snapshot);
  // Validate snapshot contains the profile state from the first update
  // This proves snapshots preserve historical profile data
  TestValidator.predicate(
    "snapshot has valid UUID",
    typeof snapshot.id === "string" && snapshot.id.length > 0,
  );
  TestValidator.equals(
    "snapshot preserves shop name",
    snapshot.shop_name,
    initialShopName,
  );
  TestValidator.equals(
    "snapshot preserves shop description",
    snapshot.shop_description,
    initialDescription,
  );
  TestValidator.predicate(
    "snapshot has seller profile reference",
    snapshot.sellerProfile !== null,
  );
  TestValidator.predicate(
    "snapshot has valid creation timestamp",
    typeof snapshot.created_at === "string" && snapshot.created_at.length > 0,
  );
  // Validate the current profile reflects the latest update
  TestValidator.equals(
    "current profile has updated name",
    finalUpdate.name,
    updatedShopName,
  );
  TestValidator.equals(
    "current profile has updated description",
    finalUpdate.description,
    updatedDescription,
  );
  TestValidator.equals(
    "current profile has updated logo",
    finalUpdate.logo_uri,
    updatedLogoUri,
  );
}

