export async function test_api_inventory_restock_variant_stock(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register and authenticate a new seller
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 2. Create a new product with required fields
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.paragraph({ sentences: 5 }),
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
        category_id: typia.random<string & tags.Format<"uuid">>(),
      },
    },
  );
  typia.assert(product);
  // 3. Create a product variant with unique SKU (quantity defaults to 0)
  const variant =
    await generate_random_ecommerce_mall_seller_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku_code: `SKU-${RandomGenerator.alphaNumeric(10).toUpperCase()}`,
          price: null,
          quantity: 0,
          option_values: [
            {
              key: "color",
              value: "Red",
            } satisfies IEcommerceMallProductVariantOptionValue.ICreate,
          ],
        },
      },
    );
  typia.assert(variant);
  // 4. Restock the variant with 100 units
  const restockQuantity = 100;
  const restockReason = "Initial stock received";
  const inventoryRecord =
    await generate_random_ecommerce_mall_seller_products_variants_inventory_adjust(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: {
          operation: "restock",
          quantity: restockQuantity,
          reason: restockReason,
        } satisfies IEcommerceMallInventoryRecord.ICreate,
      },
    );
  typia.assert(inventoryRecord);
  // 5. Validate the inventory record response
  TestValidator.equals(
    "quantity change is positive",
    inventoryRecord.quantity_change,
    restockQuantity,
  );
  TestValidator.equals(
    "calculated stock quantity equals 100",
    inventoryRecord.calculated_stock_quantity,
    100,
  );
  TestValidator.equals(
    "reason matches input",
    inventoryRecord.reason,
    restockReason,
  );
}

