export async function test_api_order_item_not_found_handling(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register and authenticate as first customer
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {});
  // 2. Generate non-existent IDs for testing
  const nonExistentOrderId = typia.random<string & tags.Format<"uuid">>();
  const nonExistentItemId = typia.random<string & tags.Format<"uuid">>();
  // 3. Test 404 for non-existent orderId
  await TestValidator.httpError(
    "non-existent orderId returns 404",
    404,
    async () => {
      await api.functional.ecommerceMall.customer.orders.items.at(
        customerConnection,
        {
          orderId: nonExistentOrderId,
          itemId: nonExistentItemId,
        },
      );
    },
  );
  // 4. Test 404 for non-existent itemId (use valid UUID format orderId)
  const validFormatOrderId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError(
    "non-existent itemId returns 404",
    404,
    async () => {
      await api.functional.ecommerceMall.customer.orders.items.at(
        customerConnection,
        {
          orderId: validFormatOrderId,
          itemId: nonExistentItemId,
        },
      );
    },
  );
  // 5. Test 404 when itemId does not belong to specified order
  // Create second customer with their own order
  const secondCustomerConnection: api.IConnection = { host: connection.host };
  const secondCustomer = await authorize_customer_join(
    secondCustomerConnection,
    {},
  );
  // Try to access second customer's order item with first customer's token
  // This should return 404 (not 403) to avoid leaking information about other orders
  if (secondCustomer.orders.length > 0) {
    const secondCustomerOrderId = secondCustomer.orders[0]!.id;
    await TestValidator.httpError(
      "itemId not belonging to order returns 404",
      404,
      async () => {
        await api.functional.ecommerceMall.customer.orders.items.at(
          customerConnection,
          {
            orderId: secondCustomerOrderId,
            itemId: nonExistentItemId,
          },
        );
      },
    );
  }
}

