export async function test_api_cancellation_request_filtering_by_status(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create customer connection
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 2. Query without status filter - should return all cancellation requests
  const allRequestsResult =
    await api.functional.ecommerceMall.customer.cancellation_requests.index(
      customerConnection,
      {
        body: {} satisfies IEcommerceMallCancellationRequest.IRequest,
      },
    );
  typia.assert(allRequestsResult);
  // 3. Query with status='pending' - should return only pending requests
  const pendingResult =
    await api.functional.ecommerceMall.customer.cancellation_requests.index(
      customerConnection,
      {
        body: {
          status: "pending",
        } satisfies IEcommerceMallCancellationRequest.IRequest,
      },
    );
  typia.assert(pendingResult);
  // 4. Query with status='approved' - should return only approved requests
  const approvedResult =
    await api.functional.ecommerceMall.customer.cancellation_requests.index(
      customerConnection,
      {
        body: {
          status: "approved",
        } satisfies IEcommerceMallCancellationRequest.IRequest,
      },
    );
  typia.assert(approvedResult);
  // 5. Query with status='rejected' - should return only rejected requests
  const rejectedResult =
    await api.functional.ecommerceMall.customer.cancellation_requests.index(
      customerConnection,
      {
        body: {
          status: "rejected",
        } satisfies IEcommerceMallCancellationRequest.IRequest,
      },
    );
  typia.assert(rejectedResult);
  // 6. Validate filtering results
  // Verify that each status filter returns only items with matching status
  for (const item of pendingResult.data) {
    TestValidator.equals("pending filter result", item.status, "pending");
  }
  for (const item of approvedResult.data) {
    TestValidator.equals("approved filter result", item.status, "approved");
  }
  for (const item of rejectedResult.data) {
    TestValidator.equals("rejected filter result", item.status, "rejected");
  }
}

