    sellerConnection,
    {
      params: {
        productId: product.id,
        variantId: variant.id,
      },
      body: {
        operation: "restock",
        quantity: 10,
        reason: "Initial inventory for testing",
      },
    },
  );
  // 6. Customer A adds item to cart
  const cartItem =
    await generate_random_ecommerce_mall_customer_cart_items_create(
      customerACustomer,
      {
        body: {
          variant_id: variant.id,
          quantity: 1,
        },
      },
    );
