    );
    // 10. Verify seller information is included
    TestValidator.predicate(
      "seller exists",
      refundRequest.seller !== null && refundRequest.seller !== undefined,
    );
    TestValidator.predicate(
      "seller has id",
      refundRequest.seller.id !== null && refundRequest.seller.id !== undefined,
