  // 11. Verify order item status changed to 'delivered'
  TestValidator.equals(
    "shipment has items",
    shipment.shipment_items.length > 0,
    true,
  );
  const deliveredItemStatus = shipment.shipment_items[0].orderItem.status;
  TestValidator.equals(
    "order item status is delivered",
    deliveredItemStatus,
    "delivered",
