export async function test_api_review_duplicate_prevention_same_order_item(
  connection: api.IConnection,
): Promise<void> {
  // <E2E TEST CODE HERE>
  // Test that duplicate review creation is prevented - attempting to create a second review
  // for the same delivered order item returns 409 Conflict.
  // Step 1: Register seller and create product with variant
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {});
  typia.assert(sellerAuth);
  // Create product with category (use a placeholder category_id - the system should handle this)
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // Create variant with stock
  const variant =
    await generate_random_ecommerce_mall_seller_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku_code: `SKU-${Date.now()}-${Math.random().toString(36).substring(7)}`,
          price: 10000,
          quantity: 10,
          option_values: [{ key: "size", value: "Large" }],
        },
      },
    );
  typia.assert(variant);
  // Step 2: Register customer and add address
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {});
  typia.assert(customerAuth);
  // Create shipping address
  const address =
    await generate_random_ecommerce_mall_customer_customers_addresses_create(
      customerConnection,
      {
        body: {
          recipient_name: "Test User",
          phone: "01012345678",
          street_address: "123 Test Street",
          city: "Seoul",
          state: "Gangnam-gu",
          postal_code: "12345",
          country: "Korea",
          is_default: true,
        },
      },
    );
  typia.assert(address);
  // Step 3: Add product to cart and checkout
  const cartItem =
    await generate_random_ecommerce_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          variant_id: variant.id,
          quantity: 1,
        },
      },
    );
  typia.assert(cartItem);
  // Checkout and create order
  const order =
    await api.functional.ecommerceMall.customer.checkout.confirm.create(
      customerConnection,
      {
        body: {
          payment_token: "mock_payment_token_success",
          address_id: address.id,
        },
      },
    );
  typia.assert(order);
  // Extract orderId and itemId
  const orderId = order.id;
  const itemId = order.orderItems[0].id;
  // Step 4: Seller ships the order
  const shipment = await generate_random_ecommerce_mall_seller_shipments_create(
    sellerConnection,
    {
      body: {
        orderId: orderId,
        orderItemIds: [itemId],
        carrier: "DHL",
        trackingNumber: "TRACK123456789",
      },
    },
  );
  typia.assert(shipment);
  // Step 5: Customer confirms delivery
  const confirmedShipment =
    await api.functional.ecommerceMall.customer.orders.shipments.confirm_delivery.confirmDelivery(
      customerConnection,
      {
        orderId: orderId,
        shipmentId: shipment.id,
      },
    );
  typia.assert(confirmedShipment);
  // Step 6: Create first review successfully
  const firstReview =
    await generate_random_ecommerce_mall_customer_customers_orders_items_review_create(
      customerConnection,
      {
        params: {
          orderId: orderId,
          itemId: itemId,
        },
        body: {
          rating: 4,
          content: "Great product!",
        },
      },
    );
  typia.assert(firstReview);
  // Step 7: Attempt to create second review for the same order item - should fail with 409
  await TestValidator.error(
    "duplicate review should fail with 409",
    async () => {
      await generate_random_ecommerce_mall_customer_customers_orders_items_review_create(
        customerConnection,
        {
          params: {
            orderId: orderId,
            itemId: itemId,
          },
          body: {
            rating: 3,
            content: "Another review attempt",
          },
        },
      );
    },
  );
}

