export async function test_api_review_snapshot_retrieval_by_owner(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create and authenticate as customer
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {});
  // 2. Create seller for the product
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {});
  // 3. Generate a review for a delivered order item (handles order creation flow internally)
  const review =
    await generate_random_ecommerce_mall_customer_customers_orders_items_review_create(
      customerConnection,
      {
        params: {
          orderId: typia.random<string & tags.Format<"uuid">>() as any,
          itemId: typia.random<string & tags.Format<"uuid">>() as any,
        },
      },
    );
  typia.assert(review);
  // 4. Edit the review multiple times to generate snapshots
  // First edit
  const updatedReview1 =
    await api.functional.ecommerceMall.customer.reviews.update(
      customerConnection,
      {
        reviewId: review.id,
        body: {
          rating: 4,
          content: "Updated review content after first edit",
        } satisfies IEcommerceMallReview.IUpdate,
      },
    );
  typia.assert(updatedReview1);
  // Second edit
  const updatedReview2 =
    await api.functional.ecommerceMall.customer.reviews.update(
      customerConnection,
      {
        reviewId: review.id,
        body: {
          rating: 5,
          content: "Final review content after second edit",
        } satisfies IEcommerceMallReview.IUpdate,
      },
    );
  typia.assert(updatedReview2);
  // 5. Retrieve paginated snapshots with pagination parameters
  const snapshotsPage =
    await api.functional.ecommerceMall.customer.reviews.snapshots.index(
      customerConnection,
      {
        reviewId: review.id,
        body: {
          page: 1,
          limit: 10,
        } satisfies IEcommerceMallReviewSnapshot.IRequest,
      },
    );
  typia.assert(snapshotsPage);
  // 6. Validate pagination metadata
  TestValidator.equals(
    "pagination current is 1",
    snapshotsPage.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit is 10",
    snapshotsPage.pagination.limit,
    10,
  );
  TestValidator.predicate(
    "pagination records >= 2",
    snapshotsPage.pagination.records >= 2,
  );
  TestValidator.predicate(
    "pagination pages >= 1",
    snapshotsPage.pagination.pages >= 1,
  );
  // 7. Validate each snapshot has required properties
  for (const snapshot of snapshotsPage.data) {
    TestValidator.predicate(
      "snapshot rating is between 1 and 5",
      snapshot.rating >= 1 && snapshot.rating <= 5,
    );
    TestValidator.predicate(
      "snapshot has valid id",
      snapshot.id !== undefined && snapshot.id.length > 0,
    );
    TestValidator.predicate(
      "snapshot has valid created_at",
      snapshot.created_at !== undefined && snapshot.created_at.length > 0,
    );
    TestValidator.predicate(
      "snapshot review_id matches",
      snapshot.review_id === review.id,
    );
    TestValidator.equals(
      "snapshot body is string or null",
      typeof snapshot.body === "string" || snapshot.body === null,
      true,
    );
  }
  // 8. Validate snapshots are ordered chronologically (oldest first)
  if (snapshotsPage.data.length >= 2) {
    for (let i = 1; i < snapshotsPage.data.length; i++) {
      const prev = new Date(snapshotsPage.data[i - 1].created_at);
      const curr = new Date(snapshotsPage.data[i].created_at);
      TestValidator.predicate(
        "snapshots are in chronological order",
        prev.getTime() <= curr.getTime(),
      );
    }
  }
}

