              },
            },
          },
        },
        seller: {
          select: {
            id: true,
            email: true,
            approval_status: true,
            created_at: true,
            profile: {
              select: {
                id: true,
                name: true,
                description: true,
              },
            },
          },
        },
        refundRequestSnapshots: {
          select: {
            id: true,
            snapshot_reason: true,
            snapshot_status: true,
            seller_response: true,
