        quantity_change: refundRequest.orderItem.quantity,
        reason: "Refund approved - inventory restored",
        created_at: now,
      },
    });
  }
  return EcommerceMallRefundRequestTransformer.transform(
    refundRequest as any,
    props.requestId,
  );
}

