    approval_status: seller.approval_status,
    rejection_reason: seller.rejection_reason,
    rejected_at:
      (seller.rejected_at?.toISOString() as string &
        tags.Format<"date-time">) ?? null,
    created_at: seller.created_at.toISOString() as string &
