import { TypedBody, TypedRoute } from "@nestia/core";
import { Controller, Ip } from "@nestjs/common";
import typia from "typia";

import { IEcommerceMallSeller } from "../../../../api/structures/IEcommerceMallSeller";
import { postEcommerceMallAuthSellerJoin } from "../../../../providers/postEcommerceMallAuthSellerJoin";
import { postEcommerceMallAuthSellerLogin } from "../../../../providers/postEcommerceMallAuthSellerLogin";
import { postEcommerceMallAuthSellerRefresh } from "../../../../providers/postEcommerceMallAuthSellerRefresh";

@Controller("/ecommerceMall/auth/seller")
export class EcommercemallAuthSellerController {
  /**
   * Registers a new seller account on the ecommerce mall platform. This endpoint creates a seller account with email and password credentials for authentication. Upon successful registration, the seller account is created with 'pending' approval status, meaning the seller cannot perform any selling activities until an administrator approves the registration. The seller will receive JWT access and refresh tokens for subsequent authenticated requests.
   *
   * The registration process captures the seller's email address (serving as unique identifier) and password for authentication. The password is securely hashed using bcrypt before storage. A new seller approval record is automatically created with 'pending' status for administrator review. The seller can check their approval status at any time using the approval-status endpoint.
   *
   * Sellers with 'pending' status can log in to their account but cannot create products, upload images, process orders, or access selling features. Only after administrator approval will the seller gain full access to selling capabilities. If registration is rejected, sellers can view the rejection reason and resubmit a new registration request.
   *
   * This operation does not require authentication as it is the initial account creation step. The endpoint returns authorization tokens that must be included in subsequent requests for authenticated operations.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Seller registration request containing email address and password credentials for new seller account creation.
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification 1. Validate incoming request body contains email and password.
   * 2. Check email format validity.
   * 3. Verify email is not already registered in ecommerce_mall_sellers table.
   * 4. Hash the password using bcrypt.
   * 5. Create new seller record with email, hashed password, and approval_status='pending'.
   * 6. Create initial seller_approval record with status='pending'.
   * 7. Generate JWT access token (short-lived, e.g., 15 minutes) and refresh token (long-lived, e.g., 7 days).
   * 8. Create session record in ecommerce_mall_seller_sessions with tokens and client metadata.
   * 9. Return access token, refresh token, seller ID, and approval status.
   * 10. Handle duplicate email conflict with appropriate error response.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEcommerceMallSeller.IJoin,
  ): Promise<IEcommerceMallSeller.IAuthorized> {
    try {
      return await postEcommerceMallAuthSellerJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Authenticates an existing seller account using email and password credentials. This endpoint validates the provided credentials against the stored seller account information and establishes an authenticated session with JWT tokens. The system checks both the email existence and password match, with security measures to prevent account enumeration attacks.
   *
   * The login process validates credentials and checks the seller's approval status. Sellers with 'pending' status can log in but have limited access until approved by an administrator. Sellers with 'approved' status can access all selling features including product management, order processing, and inventory control. Sellers with 'rejected' status can log in to view their rejection reason and submit a new registration request.
   *
   * Sellers whose accounts have been suspended by administrators cannot log in and receive an error message indicating the suspension. Suspended sellers must wait for administrator intervention to unsuspend their account before regaining access. Banned sellers are permanently blocked from login.
   *
   * Upon successful authentication, the system generates JWT access and refresh tokens stored in the seller sessions table with client metadata for security tracking. The current session remains active even if the seller changes their password on another device. All existing sessions are automatically terminated when the seller changes their password for security purposes.
   *
   * This endpoint uses a single authentication mechanism shared with customers and administrators, distinguishing account types by email and associated role. The same email cannot be registered as both a seller and other account types.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Seller login credentials containing email address and password for authentication.
   * @x-autobe-authorization-type login
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification 1. Validate incoming request body contains email and password.
   * 2. Look up seller by email in ecommerce_mall_sellers table.
   * 3. If seller not found, return generic 'invalid credentials' error (do not reveal email existence per security).
   * 4. Compare provided password with stored password_hash using bcrypt.
   * 5. Check approval_status: if 'pending', allow login but return limited session; if 'approved', full access; if 'rejected', allow login to view status and resubmit; if banned/suspended, reject login.
   * 6. Check deleted_at is null (account not deleted).
   * 7. Generate new JWT access token and refresh token.
   * 8. Create session record in ecommerce_mall_seller_sessions with client metadata (IP, browser info).
   * 9. Return tokens and seller information including approval_status.
   * 10. Handle multiple failed attempts gracefully without account lockout.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("login")
  public async login(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEcommerceMallSeller.ILogin,
  ): Promise<IEcommerceMallSeller.IAuthorized> {
    try {
      return await postEcommerceMallAuthSellerLogin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Refreshes authentication tokens for an authenticated seller session. This endpoint accepts a valid refresh token and issues a new access token, extending the session without requiring the seller to re-enter credentials. The refresh token mechanism allows for seamless continued access while maintaining security through short-lived access tokens.
   *
   * The refresh flow validates the provided refresh token against stored sessions in the ecommerce_mall_seller_sessions table. The session must belong to an active seller account (not deleted, banned, or suspended) and must not have expired. Upon successful validation, a new JWT access token is generated with a fresh expiration time.
   *
   * Refresh tokens have a longer lifespan than access tokens (typically days vs. minutes), allowing sellers to remain authenticated across multiple browsing sessions. The session record tracks client metadata including IP address and browser information for security audit purposes. Each refresh operation updates the session timestamp for activity tracking.
   *
   * Sessions are automatically invalidated when they expire or when the seller changes their password (which terminates all other sessions for security). When a refresh token expires, the seller must re-authenticate using the login endpoint. The system handles concurrent token refresh requests gracefully.
   *
   * This endpoint does not require the access token in the Authorization header since the refresh token itself serves as the authentication credential. The refresh operation is stateless regarding the access token but requires validation against the session database for the refresh token.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Token refresh request containing the current refresh token to exchange for new access and refresh tokens.
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification 1. Extract refresh token from request body.
   * 2. Validate refresh token signature and expiration.
   * 3. Look up session by refresh token in ecommerce_mall_seller_sessions table.
   * 4. Verify session belongs to an active (non-deleted, non-banned, non-suspended) seller.
   * 5. Check session has not expired (expired_at > current time).
   * 6. Generate new JWT access token (optionally new refresh token based on implementation).
   * 7. Update session record with new access token.
   * 8. Return new access token, refresh token, and seller information.
   * 9. If refresh token is expired or invalid, return appropriate error for re-authentication.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IEcommerceMallSeller.IRefresh,
  ): Promise<IEcommerceMallSeller.IAuthorized> {
    try {
      return await postEcommerceMallAuthSellerRefresh({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

